// Create i18n instance
const i18n = new I18n(translations);

// Set the locale based on device settings
i18n.locale = Localization.getLocales()[0]?.languageCode ?? 'en';

// Enable fallback to English
i18n.enableFallback = true;
i18n.defaultLocale = 'en';

// RTL Support — configure layout direction for right-to-left languages
const RTL_LANGUAGES = ['ar', 'he', 'fa', 'ur'];
export const isRTL = RTL_LANGUAGES.includes(i18n.locale);
I18nManager.allowRTL(true);
if (I18nManager.isRTL !== isRTL) {
    I18nManager.forceRTL(isRTL);
    // Note: forceRTL requires app restart to take effect
}

// Helper function to get current language code
export const getCurrentLanguage = (): string => {
    return i18n.locale;
};

// Translation function
export const t = (key: string, options?: Record<string, any>): string => {
    return i18n.t(key, options);
};

// Get translations for WebView injection
export const getWebViewTranslations = () => ({
    sharedTextInserted: t('sharedTextInserted'),
    fileAttached: t('fileAttached'),
    imageLoaded: t('imageLoaded'),
    fileReceivedNoUpload: t('fileReceivedNoUpload'),
    errorEmptyContent: t('errorEmptyContent'),
    errorEmptyFile: t('errorEmptyFile'),
    errorProcessingFile: t('errorProcessingFile'),
});

export default i18n;
